create extension if not exists pgcrypto;
create table if not exists public.careerlab_profiles(user_id uuid primary key,email text,phone text,display_name text,plan text not null default 'free',is_admin boolean not null default false,plan_started_at timestamptz,plan_expires_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.careerlab_settings(id integer primary key default 1,plans_enabled boolean not null default false,features jsonb not null default '{"resume_analysis":true,"explorer":true,"project_architecture":true,"mock_interview":true,"learning_lab":true,"job_finder":true,"answer_assistant":true}'::jsonb,limits jsonb not null default '{"visitor_explorer":3,"free_explorer_daily":10,"free_mock_daily":2,"visitor_signin_after":3}'::jsonb,pro_price_paise integer not null default 49900,plan_copy jsonb not null default '{"free":["Resume analysis","Basic Explorer","Limited practice"],"pro":["Advanced interview coaching","Higher usage limits","Personalized learning","Job discovery"]}'::jsonb,updated_at timestamptz not null default now());
create table if not exists public.careerlab_usage(id bigint generated by default as identity primary key,user_id uuid,visitor_id text,feature text not null,usage_date date not null default current_date,count integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,feature,usage_date),unique(visitor_id,feature,usage_date));
create table if not exists public.careerlab_payments(id bigint generated by default as identity primary key,user_id uuid not null,email text,phone text,razorpay_order_id text unique not null,razorpay_payment_id text,razorpay_signature text,amount integer not null,currency text not null default 'INR',plan text not null default 'pro',status text not null default 'created',receipt_number text unique,created_at timestamptz not null default now(),verified_at timestamptz);
create table if not exists public.careerlab_notifications(id bigint generated by default as identity primary key,user_id uuid,channel text not null,status text not null,recipient text,message text,created_at timestamptz not null default now());
insert into public.careerlab_settings(id) values(1) on conflict(id) do nothing;
alter table public.careerlab_profiles enable row level security;alter table public.careerlab_settings enable row level security;alter table public.careerlab_usage enable row level security;alter table public.careerlab_payments enable row level security;alter table public.careerlab_notifications enable row level security;
revoke all on public.careerlab_profiles from anon,authenticated;revoke all on public.careerlab_settings from anon,authenticated;revoke all on public.careerlab_usage from anon,authenticated;revoke all on public.careerlab_payments from anon,authenticated;revoke all on public.careerlab_notifications from anon,authenticated;
grant all on public.careerlab_profiles,public.careerlab_settings,public.careerlab_usage,public.careerlab_payments,public.careerlab_notifications to service_role;
grant usage,select on all sequences in schema public to service_role;
